cat > sum.js <<'EOF'
function sum(a, b) { return a + b; }
module.exports = { sum };
EOF

cat > sum.test.js <<'EOF'
const assert = require('assert');
const { sum } = require('./sum');
assert.strictEqual(sum(2, 3), 5);
assert.strictEqual(sum(-1, 1), 0);
console.log('AC1_OK: sum adds two numbers');
EOF

